steps.code:
[[extensions]]
name = "Regras de cumprimento"
handle = "regras-cumprimento"
type = "function"

  [[extensions.targeting]]
  target = "cart.fulfillment-constraints.generate.run"
  input_query = "src/cart_fulfillment_constraints_generate_run.graphql"
  export = "cart-fulfillment-constraints-generate-run"

query CartFulfillmentConstraintsGenerateRunInput {
  cart {
    deliverableLines {
      id
    }
  }
  locations {
    id
    metafield(namespace: "custom", key: "tipo") {
      value
    }
  }
  fulfillmentConstraintRule {
    metafield(namespace: "$app:config", key: "limites") {
      jsonValue
    }
  }
}

// src/cart_fulfillment_constraints_generate_run.js
// Pedidos com mais de N itens só saem de depósitos (não de lojas físicas).
export function cartFulfillmentConstraintsGenerateRun(input) {
  const itemLimit = input.fulfillmentConstraintRule?.metafield?.jsonValue?.itemLimit ?? Infinity;

  if (input.cart.deliverableLines.length <= itemLimit) {
    return { operations: [] };
  }

  const depositos = input.locations
    .filter((location) => location.metafield?.value === "deposito")
    .map((location) => location.id);

  return {
    operations: [
      {
        deliverableLinesMustFulfillFromAdd: {
          deliverableLineIds: input.cart.deliverableLines.map((line) => line.id),
          locationIds: depositos,
        },
      },
    ],
  };
}

// "tudo do mesmo lugar": kits precisam sair juntos de uma única localização
{
  deliverableLinesMustFulfillFromSameLocationAdd: {
    deliverableLineIds: input.cart.deliverableLines.map((line) => line.id),
  },
}

// Order Routing (Location Rule) — só Shopify Plus, sob solicitação.
// target: cart.fulfillment-groups.location-rankings.generate.run
export function cartFulfillmentGroupsLocationRankingsGenerateRun(input) {
  const operations = input.fulfillmentGroups.map((group) => {
    // menor rank = maior prioridade; localizações omitidas ficam por último
    const rankings = (group.inventoryLocationHandles ?? []).map((handle, index) => ({
      locationHandle: handle,
      rank: index,
    }));

    return {
      fulfillmentGroupLocationRankingAdd: {
        fulfillmentGroupHandle: group.handle,
        rankings,
      },
    };
  });

  return { operations };
}
